/*
 * test_gesture.c - scripted-scenario driver for firmware/src/gesture.c (ticket 3.7T).
 *
 * Runs the REAL modules (lis3dh, capture, trigger, features, mlp, knn, classify, c2_stream, gesture)
 * against a fake LIS3DH (fake_sensor.c) and a fake board port (below: TX ring capture, settable
 * millis, settable INT flags). The scenarios are op lists generated by run_tests.py into scen.h
 * (so Python and C cannot disagree about them); the Python side re-derives every expectation from
 * the SPEC references (tools/trigger_ref.py, tools/infer_ref.py, tools/c2_proto.py). This file only
 * produces observations, one short text line each (simavr splits lines > 255 characters):
 *   M hash8 conf_shift default_reject   model identity (mlp_model_info)
 *   S name                              scenario start
 *   R <what> <values...>                result of an API call (init, poll, classify, learn, events)
 *   P step                              gesture_poll() went false -> true (during an SEG/STALL step)
 *   X step hex...                       TX bytes that left the fake UART during that step (<= 96 B/line)
 *   G first count                       FIFO samples discarded by the fake sensor (seq range)
 *   T n min max                         drain intervals seen (ms), see OP_SEG
 *   V text                              harness violation (e.g. gesture.c wrote more than port_tx_room)
 *   DONE                                end
 * One step = one sensor sample = 10 ms. Sample generator (mirrored in run_tests.py): LCG noise
 * {-3..3} per axis plus a triangle-wave swing, see gen_sample().
 *
 * Host: ./test_gesture_host [scenario_index]  (no argument: all). sim16: compiled-in scenario list.
 */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "sim16.h"
#include "gesture.h"
#include "gesture_port.h"
#include "gesture_ids.h"
#include "mlp.h"
#include "fake_sensor.h"
#include "scen.h"      /* generated: OP_* codes, op_t, scen_t, SCEN[], N_SCEN */

/* ------------------------------------------------------------------ fake board port */
static uint8_t  ring[256];
static uint16_t ring_head, ring_n, ring_cap = 128u;   /* ring_cap <= 255 (port_tx_room is a uint8) */
static uint16_t ms16;
static bool     fifo_flag, click_flag;
static bool     viol_txover;

uint8_t port_tx_room(void) { return (uint8_t)(ring_cap - ring_n); }

void port_tx_write(const uint8_t *p, uint8_t n)
{
    uint8_t i;
    for (i = 0u; i < n; i++) {
        if (ring_n >= ring_cap) { viol_txover = true; return; }
        ring[(uint16_t)((ring_head + ring_n) % 256u)] = p[i];
        ring_n++;
    }
}

uint16_t port_millis(void) { return ms16; }
bool port_take_fifo_flag(void) { bool f = fifo_flag; fifo_flag = false; return f; }
bool port_take_click_flag(void) { bool f = click_flag; click_flag = false; return f; }

/* ------------------------------------------------------------------ output helpers */
static uint8_t  stepbuf[96];
static uint8_t  stepn;
static uint16_t step_no;

static void flush_x(void)
{
    uint8_t i;
    if (stepn == 0u) { return; }
    printf("X %u ", (unsigned)step_no);
    for (i = 0u; i < stepn; i++) { printf("%02x", (unsigned)stepbuf[i]); }
    printf("\n");
    stepn = 0u;
}

/** The fake UART: remove up to n bytes from the TX ring and record them for this step. */
static void uart_drain(uint16_t n)
{
    while (n > 0u && ring_n > 0u) {
        if (stepn == sizeof stepbuf) { flush_x(); }
        stepbuf[stepn++] = ring[ring_head];
        ring_head = (uint16_t)((ring_head + 1u) % 256u);
        ring_n--;
        n--;
    }
}

/* ------------------------------------------------------------------ sample generator (mirrored in Python) */
static uint32_t lcg;

static int16_t noise(void)
{
    lcg = lcg * 1664525u + 1013904223u;
    return (int16_t)((int16_t)((lcg >> 16) % 7u) - 3);
}

static int16_t tri(int16_t j, int16_t per)
{
    int16_t u = (int16_t)(j % per), h = (int16_t)(per / 2), v = (u < h) ? u : (int16_t)(per - u);
    return (int16_t)(v - per / 4);
}

static int16_t clamp12(int32_t v)
{
    return (int16_t)(v < -2048 ? -2048 : (v > 2047 ? 2047 : v));
}

static void gen_sample(int16_t j, const op_t *o, int16_t s[3])
{
    int16_t nx = noise(), ny = noise(), nz = noise();
    s[0] = clamp12((int32_t)o->a * tri(j, o->p) + nx);
    s[1] = clamp12((int32_t)o->b * tri((int16_t)(j + 3), o->p) + ny);
    s[2] = clamp12(512 + (int32_t)o->c * tri((int16_t)(j + 5), o->p) + nz);
}

/* ------------------------------------------------------------------ run state */
static uint8_t  polls_per_step = 2u;
static uint16_t rate_per_poll = 64u;
static uint8_t  flag_mode;          /* 0: INT0 flag when FIFO unread reaches 16 (watermark); 1: never; 2: every step */
static bool     autoclass;
static bool     was_true;
static uint16_t ndrain, dmin, dmax, last_drain_ms;
static bool     have_last_drain;

/** One gesture_poll() call plus the fake UART drain; prints a P line on a false -> true change. */
static void do_poll(void)
{
    uint8_t before = fs_level(), after;
    bool r = gesture_poll();
    after = fs_level();
    if (after < before) {
        uint16_t d = (uint16_t)(ms16 - last_drain_ms);
        if (have_last_drain) {
            ndrain++;
            if (ndrain == 1u || d < dmin) { dmin = d; }
            if (d > dmax) { dmax = d; }
        }
        have_last_drain = true;
        last_drain_ms = ms16;
    }
    if (r && !was_true) { flush_x(); printf("P %u\n", (unsigned)step_no); }
    was_true = r;
    if (r && autoclass) {
        uint8_t conf = 0xEEu;
        int8_t id = gesture_classify(&conf);
        printf("R classify %d %u\n", (int)id, (unsigned)conf);
        was_true = false;
    }
    uart_drain(rate_per_poll);
}

/** One 10 ms step: optionally generate+push a sample, advance time, set INT0 flag, poll P times. */
static void do_step(int16_t j, const op_t *o, bool poll)
{
    int16_t s[3];
    uint8_t before = fs_level(), p;
    gen_sample(j, o, s);
    fs_push(s);
    step_no++;
    ms16 = (uint16_t)(ms16 + 10u);
    if (flag_mode == 2u || (flag_mode == 0u && before < 16u && fs_level() >= 16u)) { fifo_flag = true; }
    if (poll) {
        for (p = 0u; p < polls_per_step; p++) { do_poll(); }
    } else {
        uart_drain((uint16_t)(rate_per_poll * polls_per_step));
    }
    flush_x();
}

static void run_scenario(const scen_t *sc)
{
    uint16_t i, k, g0, g1;
    printf("S %s\n", sc->name);
    viol_txover = false;
    ring_head = ring_n = 0u;
    ring_cap = 128u; ms16 = 0u; fifo_flag = click_flag = false;
    polls_per_step = 2u; rate_per_poll = 64u; flag_mode = 0u; autoclass = false; was_true = false;
    ndrain = 0u; dmin = dmax = 0u; have_last_drain = false; step_no = 0u; stepn = 0u;
    fs_reset(0x18u, 0x33u, 0xFFu);
    for (i = 0u; i < sc->nops; i++) {
        const op_t *o = &sc->ops[i];
        uint8_t conf;
        int8_t r;
        switch (o->k) {
        case OP_BEGIN:  lcg = (uint32_t)(uint16_t)o->n; break;
        case OP_SENSOR: fs_reset((uint8_t)o->n, (uint8_t)o->a, (uint8_t)o->b); break;
        case OP_CFG:
            ring_cap = (uint16_t)o->n; rate_per_poll = (uint16_t)o->a; polls_per_step = (uint8_t)o->b;
            flag_mode = (uint8_t)o->c; ms16 = (uint16_t)o->p;
            break;
        case OP_INIT:
            r = gesture_init((uint8_t)o->n, (uint8_t)o->a);
            printf("R init %d\n", (int)r);
            have_last_drain = false; ndrain = 0u;
            break;
        case OP_SEG:
        case OP_STALL:
            for (k = 0u; k < (uint16_t)o->n; k++) { do_step((int16_t)k, o, o->k == OP_SEG); }
            break;
        case OP_POLL:   flush_x(); printf("R poll %d\n", (int)gesture_poll()); break;
        case OP_CLASSIFY:
            conf = 0xEEu;
            r = gesture_classify(o->n ? NULL : &conf);
            printf("R classify %d %u\n", (int)r, (unsigned)(o->n ? 0u : conf));
            break;
        case OP_LEARN:  printf("R learn %d\n", (int)gesture_learn((uint8_t)o->n)); break;
        case OP_REJECT: gesture_set_reject((uint8_t)o->n); break;
        case OP_STREAM: gesture_stream_raw(o->n != 0); break;
        case OP_EVENTS: printf("R events %u\n", (unsigned)gesture_events()); break;
        case OP_CLICK:
            fs_set_click(o->n == 0 ? 0x60u : 0x50u);   /* CLICK_SRC: IA|DCLICK, or IA|SCLICK */
            click_flag = true;
            break;
        case OP_AUTO:   autoclass = (o->n != 0); break;
        default: printf("V bad op %u\n", (unsigned)o->k); break;
        }
    }
    flush_x();
    for (k = 0u; k < fs_gap_count(); k++) {
        fs_gap((uint8_t)k, &g0, &g1);
        printf("G %u %u\n", (unsigned)g0, (unsigned)g1);
    }
    printf("T %u %u %u\n", (unsigned)ndrain, (unsigned)dmin, (unsigned)dmax);
    if (viol_txover) { printf("V gesture.c wrote more than port_tx_room()\n"); }
}

#ifndef TEST_ONLY
#define TEST_ONLY (-1)
#endif

int main(int argc, char **argv)
{
    uint16_t i;
    int16_t only = TEST_ONLY;
    mlp_model_info_t mi;
    sim16_init();
#ifndef __AVR__
    if (argc > 1) { only = (int16_t)atoi(argv[1]); }
#else
    (void)argc; (void)argv;
#endif
    mlp_model_info(&mi);
    printf("M %08lX %u %u\n", (unsigned long)mi.model_hash, (unsigned)mi.conf_shift, (unsigned)mi.default_reject);
    for (i = 0u; i < N_SCEN; i++) {
        if (only >= 0 && (int16_t)i != only) { continue; }
        run_scenario(&SCEN[i]);
    }
    printf("DONE\n");
    sim16_exit(0);
    return 0;
}
